/* PHRASE_FUNK_BASS — 試聴5周目①グループで使った「オクターブ往復の
   ファンクベース」（James Jamerson的な、根音→オクターブ→5度と動く形）。
   BASSは{c}が和音の積みの何番目か（0=ルート/1=5度/2=オクターブ/3=3度）
   なので、絶対音名ではなく元のcard-audition5.jsのインターバル(0/12/7半音)を
   そのままc(0/2/1)に対応させればよく、変換に丸め誤差は生じない。
   コードが変わっても同じ動きの形が保たれるので4小節とも同一パターン。 */
const FUNK_BASS_BAR = [
  { s: 0,  c: 0, v: .85, l: '4n' }, { s: 3,  c: 2, v: .42, l: '16n' },
  { s: 6,  c: 1, v: .48, l: '16n' }, { s: 8,  c: 0, v: .82, l: '4n' },
  { s: 11, c: 2, v: .38, l: '16n' }, { s: 14, c: 1, v: .52, l: '16n' },
];
const PHRASE_FUNK_BASS = [FUNK_BASS_BAR, FUNK_BASS_BAR, FUNK_BASS_BAR, FUNK_BASS_BAR];

