     既存の『ハードロック』世界（key:i）は歪んだギターの壁・148BPMだが、
     こちらは真逆の性格：歪みなし、明るいツインギターの合いの手、
     ピアノのブギウギ、ウォーキングベース、跳ねる（シャッフル）ドラム。
