/* スタイルカードとして出せる18枚（base は札を持たない＝初期状態）。
   先頭15枚はキーの並び（6 7 8 9 0 Y U P I O H J L K N）と同じ。
   16枚目以降（ヴィンテージジャズポップ・モダンポップ・サンシャイン
   ポップ）は、26キー使い切りにより`key`を持たない＝キーボード
   ショートカットなし（マウス・石では今までどおり選べる。
   app.js 5章のコメント参照）。
   前半7枚が v10 まで、次の5枚が v11、モータウンが v12（stone-app-v6）、
   ロックンロールが v14（stone-app-v8）、
   レトロシンセポップが v15（stone-app-v9）、
   ヴィンテージジャズポップが v16（stone-app-v10）、
   モダンポップが v17（stone-app-v11）、
   最後のサンシャインポップが v19（stone-app-v13）で
   試聴データ／引継ぎ記録の参考曲クラスタから足したもの。
   これで引継ぎ記録の9クラスタ①〜⑨が全て実装済みになった
   （④は久石譲世界で代替）。 */
const WORLD_ORDER = [
  'beatles', 'kaze', 'modal', 'hisaishi', 'citypop', 'house', 'lofi',
  'funk', 'rock', 'reggae', 'flamenco', 'swing', 'motown', 'rocknroll',
  'synthpop', 'vintagejazz', 'modernpop', 'sunshinepop',
];

/* ---------------------------------------------------------------------
   いま有効な世界。key が null なら base（標準）。
   engine.js と app.js はここだけを見る。                              */
const World = {
  key: null,
  def: WORLDS.base,

  set(key) {
    this.key = (key && WORLDS[key] && key !== 'base') ? key : null;
    this.def = this.key ? WORLDS[this.key] : WORLDS.base;
  },
  label() { return this.def.label; },

  /* v31（作り直し）：メロディ拡張枠（ext1〜ext5）の中身。世界が
     `extMelodies`にその位置ぶんの定義を持っていればそれを返し、
     無ければnull＝「この世界にはまだ無い札」（共通の既定へは
     フォールバックしない。世界の数だけムードを使い回すことを
     やめたのが今回の作り直しの核心）。 */
  extDef(charKey) {
    const i = EXT_SLOTS.indexOf(charKey);
    if (i < 0) return null;
    const list = this.def.extMelodies;
    return (list && list[i]) ? list[i] : null;
  },
  /* その札（キャラクター × 役割）を、いまの世界では何で鳴らすか */
  layersFor(charKey, roleKey) {
    const ext = this.extDef(charKey);
    if (ext) return ext.voices;
    const v = this.def.voices[charKey];
    return (v && v[roleKey]) ? v[roleKey] : WORLDS.base.voices[charKey][roleKey];
  },
  /* v13（stone-app-v7）：世界が「この札だけは専用の譜面を持つ」と
     言っていれば、共有のPHRASESの代わりにそちらを使う。
     無ければ null を返し、呼び出し側（engine.js）は今までどおり
     PHRASES[charKey][roleKey] を使う＝既存の全世界は無変更で動く。 */
  phraseFor(charKey, roleKey) {
    const ext = this.extDef(charKey);
    if (ext) return ext.phrase;
    const o = this.def.phraseOverrides;
    return (o && o[charKey] && o[charKey][roleKey]) ? o[charKey][roleKey] : null;
  },
  kit(k) { return this.def.kit || k; },
  voicingKind(k) {
    const m = this.def.voicingMap || {};
    return (k in m) ? m[k] : k;
  },
  drum(p) {
    const m = this.def.drumMap || {};
    return (p in m) ? m[p] : p;
  },
  harmony() { return this.def.harmony || null; },
  /* 土台のビート（札が0枚のときに鳴っている、その世界のグルーヴ） */
  groove() { return GROOVES[this.def.groove] || GROOVES.eight; },
  /* 「この役割は裏拍で鳴らす」（8-a章）。いまはレゲエの和音だけが使う */
  offbeat() { return this.def.offbeat || null; },
  move() { return this.num('move', 2); },
  num(field, dflt) { return this.def[field] == null ? dflt : this.def[field]; },
  sendScale()  { return this.num('sendScale', 1); },
  delayScale() { return this.num('delayScale', 1); },
  panScale()   { return this.num('panScale', 1); },
  drumGain()   { return this.num('drumGain', 0); },
  energyScale(){ return this.num('energyScale', 1); },
};
